pub(crate) fn st_stroke(mut pa: &mut crate::port::Cells, mut pts: &mut crate::port::Cells, x0: i32, y0: i32, segs: i32) -> i32 {
    // An open stroked curve of `segs` Bezier segments from (x0, y0), 800 wide each and 1500 high; answers its row.
    let first: i32 = crate::port::cells_len(pts) / 3;
    let mut k: i32 = 0;
    let r: i32 = pa_new(pa, 1, pa_curve(), x0, y0, x0 + (segs * 800), y0 + 1500);
    pt_add(pts, x0, y0, po_move());
    while k < segs {
        pt_add(pts, x0 + (k * 800), y0 + 1500, po_curve());
        pt_add(pts, x0 + (k * 800) + 400, y0, po_curve());
        pt_add(pts, x0 + ((k + 1) * 800), y0 + 700, po_curve());
        k += 1;
    }
    pa_set(pa, r, pf_flags(), pg_stroked());
    pa_set(pa, r, pf_stroke(), 2047903);
    pa_set(pa, r, pf_width(), 140);
    pa_set(pa, r, pf_pfirst(), first);
    pa_set(pa, r, pf_pcount(), 1 + (segs * 3));
    return r;
}
